from itertools import product
from math import exp
s=lambda x: 1/(1+exp(-x))
p={}
for h,v,c,r,y in product([0,1],repeat=5):
 hv=1/6 if h==v else 1/3
 pr=s(.75*h+.5*c)
 py=s(-.5+2.5*v+1.75*c)
 p[h,v,c,r,y]=hv*.5*(pr if r else 1-pr)*(py if y else 1-py)
def cond_y(**given):
 axes={'h':0,'v':1,'c':2,'r':3}
 selected=[(x,w) for x,w in p.items() if all(x[axes[k]]==v for k,v in given.items())]
 return sum(w*x[4] for x,w in selected)/sum(w for x,w in selected)
for h in [0,1]: print(f'P(Y=1 | H={h})={cond_y(h=h):.6f}')
for c in [0,1]:
 for r in [0,1]: print(f'P(Y=1 | C={c}, R={r})={cond_y(c=c,r=r):.6f}')
print('Bayes accuracy with V,C:',sum(max(s(-.5+2.5*v+1.75*c),1-s(-.5+2.5*v+1.75*c))*.25 for v,c in product([0,1],repeat=2)))
print('Overall P(Y=1):',cond_y())
print('Reported bird split sum:',2849+520+529)
