/bin/bash -c "python3 - <<'PY'
from itertools import combinations
original=[('U','H'),('U','V'),('H','R'),('C','R'),('C','Y'),('V','Y')]
alternative=[('H','V'),('H','R'),('C','R'),('C','Y'),('V','Y')]
observed=['H','V','R','Y']
def independencies(edges):
 edges=set(edges)
 nodes=set(sum(([a,b] for a,b in edges),[]))
 neighbors={a:{b for x,b in edges if x==a}|{b for b,x in edges if x==a} for a in nodes}
 def sep(a,b,z):
  anc=set(z)
  while True:
   extra={x for x,y in edges if y in anc}
   if extra <= anc: break
   anc |= extra
  def open_path(path):
   for i,m in enumerate(path[1:-1],1):
    collider=(path[i-1],m) in edges and (path[i+1],m) in edges
    if (collider and m not in anc) or (not collider and m in z):return False
   return True
  def search(path):
   last=path[-1]
   if last==b:return open_path(path)
   return any(search(path+[n]) for n in neighbors[last] if n not in path)
  return not search([a])
 out=[]
 for a,b in combinations(observed,2):
  rest=[n for n in observed if n not in [a,b]]
  for k in range(len(rest)+1):
   for z in combinations(rest,k):
    if sep(a,b,set(z)):out.append((a,b,z))
 return out
print('Original observed d-separations:',independencies(original))
print('Alternative with H -> V -> Y:',independencies(alternative))
print('Identical:',independencies(original)==independencies(alternative))
PY"
